import{lstat}from'node:fs/promises';import{basename}from'node:path';import{spawn}from'node:child_process';export function assertBiliRestoreScope(session,args,expectedSession,block){if(session!==expectedSession||args.blockId!==block||args.full!==true||Object.hasOwn(args,'toFile'))throw Error('DECOMPRESS_SCOPE_DENIED');}export function assertBiliRuntimeFence(meta){if(meta.execIsNode!==false||meta.regular!==true||meta.symlink!==false||meta.links!==1||!Number.isInteger(meta.mode)||(meta.mode&0o111)!==0||meta.bytes!==0||meta.errno!=='EACCES')throw Error('BILI_RUNTIME_FENCE_NOT_VERIFIED');}export function applyValidatedBiliHeaders(headers,facts,pid,model){if(facts.pid!==pid)throw Error('BILI_FACT_EPOCH_MISMATCH');const fact=facts.models.find(m=>m.providerID===model?.providerID&&m.id===model?.id);if(!fact||!Number.isSafeInteger(fact.context)||!Number.isSafeInteger(fact.output)||fact.context<=0||fact.output<=0)throw Error('BILI_FACTS_UNVERIFIED');const pairs=[['x-bili-plugin-context-window',fact.context],['x-bili-plugin-max-output',fact.output]];for(const[k,v]of pairs){const existing=headers.get(k);if(existing!==null&&existing!==String(v))throw Error('BILI_MODEL_FACT_HEADER_MISMATCH');}let filled=0;for(const[k,v]of pairs)if(headers.get(k)===null){headers.set(k,String(v));filled++;}return filled;}export async function installBiliSpawnGuard(packageRoot,onDenied,file){const stat=await lstat(file),execIsNode=['node','node.exe'].includes(basename(process.execPath).toLowerCase());if(execIsNode||!stat.isFile()||stat.isSymbolicLink()||stat.nlink!==1||(stat.mode&0o111)!==0||stat.size!==0)throw Error('BILI_RUNTIME_OVERRIDE_UNSAFE');process.env.BILLION_CONTEXT_NODE=file;let errno;const child=spawn(file,[packageRoot+'/dist/index.js','start']);child.on('error',e=>{errno=e.code;});await new Promise(r=>child.once('close',r));assertBiliRuntimeFence({execIsNode,regular:stat.isFile(),symlink:stat.isSymbolicLink(),links:stat.nlink,mode:stat.mode,bytes:stat.size,errno});onDenied('selftest');return{runtime_override:true,eacces_verified:true};}
